=============== core/RV32core.v
     1	`timescale 1ns / 1ps
     2	
     3	
     4	module  RV32core(
     5	        input debug_en,  // debug enable
     6	        input debug_step,  // debug step clock
     7	        input [6:0] debug_addr,  // debug address
     8	        output[31:0] debug_data,  // debug data
     9	        input clk,  // main clock
    10	        input rst,  // synchronous reset
    11	        input interrupter,  // interrupt source, for future use
    12	
    13	        // debug info
    14	        output[31:0] pc,
    15	        output[31:0] inst,
    16	        output[31:0] mem_addr,
    17	        output[31:0] mem_data
    18	    );
    19	
    20	    wire debug_clk;
    21	
    22	    debug_clk clock(.clk(clk),.debug_en(debug_en),.debug_step(debug_step),.debug_clk(debug_clk));
    23	
    24	    wire Branch_ctrl, JALR, RegWrite_ctrl, mem_w_ctrl, MIO_ctrl,
    25	        ALUSrc_A_ctrl, ALUSrc_B_ctrl, DatatoReg_ctrl, rs1use_ctrl, rs2use_ctrl;
    26	    wire[1:0] hazard_optype_ctrl;
    27	    wire[2:0] ImmSel_ctrl, cmp_ctrl;
    28	    wire[3:0] ALUControl_ctrl;
    29	
    30	    wire forward_ctrl_ls;
    31	    wire[1:0] forward_ctrl_A, forward_ctrl_B;
    32	
    33	    wire PC_EN_IF;
    34	    wire [31:0] PC_IF, next_PC_IF, PC_4_IF, inst_IF;
    35	
    36	    wire reg_FD_EN,reg_FD_stall,reg_FD_flush, cmp_res_ID;
    37	    wire [31:0] jump_PC_ID, PC_ID, inst_ID, Debug_regs, rs1_data_reg, rs2_data_reg,
    38	        Imm_out_ID, rs1_data_ID, rs2_data_ID, addA_ID;
    39	    
    40	    wire reg_DE_EN, reg_DE_flush, RegWrite_EXE, mem_w_EXE, MIO_EXE,
    41	        ALUSrc_A_EXE, ALUSrc_B_EXE, ALUzero_EXE, ALUoverflow_EXE, DatatoReg_EXE;
    42	    wire[2:0] u_b_h_w_EXE;
    43	    wire[3:0] ALUControl_EXE;
    44	    wire[4:0] rs1_EXE, rs2_EXE, rd_EXE;
    45	    wire[31:0] ALUout_EXE, PC_EXE, inst_EXE, rs1_data_EXE, rs2_data_EXE, Imm_EXE,
    46	        ALUA_EXE, ALUB_EXE, Dataout_EXE;
    47	    
    48	    wire reg_EM_EN, reg_EM_flush, RegWrite_MEM, DatatoReg_MEM, mem_w_MEM, MIO_MEM;
    49	    wire[2:0] u_b_h_w_MEM;
    50	    wire[4:0] rd_MEM;
    51	    wire[31:0] ALUout_MEM, PC_MEM, inst_MEM, Dataout_MEM, Datain_MEM;
    52	
    53	
    54	    wire reg_MW_EN, RegWrite_WB, DatatoReg_WB;
    55	    wire[4:0] rd_WB;
    56	    wire [31:0] wt_data_WB, PC_WB, inst_WB, ALUout_WB, Datain_WB;
    57	
    58	
    59	    // IF
    60	    REG32 REG_PC(.clk(debug_clk),.rst(rst),.CE(PC_EN_IF),.D(next_PC_IF),.Q(PC_IF));
    61	    
    62	    add_32 add_IF(.a(PC_IF),.b(32'd4),.c(PC_4_IF));
    63	
    64	    // 跳转在 ID 段判定：Branch_ctrl 为 1 时取 ID 段算出的跳转地址
    65	    MUX2T1_32 mux_IF(.I0(PC_4_IF),.I1(jump_PC_ID),.s(Branch_ctrl),.o(next_PC_IF));
    66	
    67	    ROM_D inst_rom(.a(PC_IF[8:2]),.spo(inst_IF));
    68	
    69	
    70	    // ID
    71	    REG_IF_ID reg_IF_ID(.clk(debug_clk),.rst(rst),.EN(reg_FD_EN),.Data_stall(reg_FD_stall),
    72	        .flush(reg_FD_flush),.PCOUT(PC_IF),.IR(inst_IF),
    73	
    74	        .IR_ID(inst_ID),.PCurrent_ID(PC_ID));
    75	    
    76	    CtrlUnit ctrl(.inst(inst_ID),.cmp_res(cmp_res_ID),.Branch(Branch_ctrl),.ALUSrc_A(ALUSrc_A_ctrl),
    77	        .ALUSrc_B(ALUSrc_B_ctrl),.DatatoReg(DatatoReg_ctrl),.RegWrite(RegWrite_ctrl),
    78	        .mem_w(mem_w_ctrl),.MIO(MIO_ctrl),.rs1use(rs1use_ctrl),.rs2use(rs2use_ctrl),
    79	        .hazard_optype(hazard_optype_ctrl),.ImmSel(ImmSel_ctrl),.cmp_ctrl(cmp_ctrl),
    80	        .ALUControl(ALUControl_ctrl),.JALR(JALR));
    81	    
    82	    Regs register(.clk(debug_clk),.rst(rst),.L_S(RegWrite_WB),.R_addr_A(inst_ID[19:15]),
    83	        .R_addr_B(inst_ID[24:20]),.rdata_A(rs1_data_reg),.rdata_B(rs2_data_reg),
    84	        .Wt_addr(rd_WB),.Wt_data(wt_data_WB),
    85	        .Debug_addr(debug_addr[4:0]),.Debug_regs(Debug_regs));
    86	    
    87	    ImmGen imm_gen(.ImmSel(ImmSel_ctrl),.inst_field(inst_ID),.Imm_out(Imm_out_ID));
    88	    
    89	    // MEM 段可以前递出去的数据：load 用 RAM 的读出数据（RAM_B 是组合读，
    90	    // load 处于 MEM 段时数据已经有效），其它指令用 ALU 的结果
    91	    wire [31:0] mem_fwd_data = DatatoReg_MEM ? Datain_MEM : ALUout_MEM;
    92	
    93	    // 前递多路选择器 — forward_ctrl: 00=寄存器堆, 01=MEM 段结果
    94	    MUX4T1_32 mux_forward_A(.I0(rs1_data_reg),.I1(mem_fwd_data),.I2(32'b0),.I3(32'b0),
    95	        .s(forward_ctrl_A),.o(rs1_data_ID));
    96	
    97	    MUX4T1_32 mux_forward_B(.I0(rs2_data_reg),.I1(mem_fwd_data),.I2(32'b0),.I3(32'b0),
    98	        .s(forward_ctrl_B),.o(rs2_data_ID));
    99	    
   100	    MUX2T1_32 mux_branch_ID(.I0(PC_ID),.I1(rs1_data_ID),.s(JALR),.o(addA_ID));
   101	
   102	    add_32 add_branch_ID(.a(addA_ID),.b(Imm_out_ID),.c(jump_PC_ID));
   103	
   104	    cmp_32 cmp_ID(.a(rs1_data_ID),.b(rs2_data_ID),.ctrl(cmp_ctrl),.c(cmp_res_ID));        
   105	    
   106	    HazardDetectionUnit hazard_unit(.clk(debug_clk),.Branch_ID(Branch_ctrl),.rs1use_ID(rs1use_ctrl),
   107	        .rs2use_ID(rs2use_ctrl),.hazard_optype_ID(hazard_optype_ctrl),.rd_EXE(rd_EXE),
   108	        .rd_MEM(rd_MEM),.rs1_ID(inst_ID[19:15]),.rs2_ID(inst_ID[24:20]),.rs2_EXE(rs2_EXE),
   109	        .PC_EN_IF(PC_EN_IF),.reg_FD_EN(reg_FD_EN),.reg_FD_stall(reg_FD_stall),
   110	        .reg_FD_flush(reg_FD_flush),.reg_DE_EN(reg_DE_EN),.reg_DE_flush(reg_DE_flush),
   111	       .reg_EM_EN(reg_EM_EN),.reg_EM_flush(reg_EM_flush),.reg_MW_EN(reg_MW_EN),
   112	        .forward_ctrl_ls(forward_ctrl_ls),.forward_ctrl_A(forward_ctrl_A),
   113	        .forward_ctrl_B(forward_ctrl_B));
   114	
   115	
   116	    // EX
   117	    REG_ID_EX reg_ID_EX(.clk(debug_clk),.rst(rst),.EN(reg_DE_EN),.flush(reg_DE_flush),.IR_ID(inst_ID),
   118	        .PCurrent_ID(PC_ID),.rs1_addr(inst_ID[19:15]),.rs2_addr(inst_ID[24:20]),.rs1_data(rs1_data_ID),
   119	        .rs2_data(rs2_data_ID),.Imm32(Imm_out_ID),.rd_addr(inst_ID[11:7]),.ALUSrc_A(ALUSrc_A_ctrl),
   120	        .ALUSrc_B(ALUSrc_B_ctrl),.ALUC(ALUControl_ctrl),.DatatoReg(DatatoReg_ctrl),
   121	        .RegWrite(RegWrite_ctrl),.WR(mem_w_ctrl),.u_b_h_w(inst_ID[14:12]),.MIO(MIO_ctrl),
   122	
   123	        .PCurrent_EX(PC_EXE),.IR_EX(inst_EXE),.rs1_EX(rs1_EXE),.rs2_EX(rs2_EXE),
   124	        .A_EX(rs1_data_EXE),.B_EX(rs2_data_EXE),.Imm32_EX(Imm_EXE),.rd_EX(rd_EXE),
   125	        .ALUSrc_A_EX(ALUSrc_A_EXE),.ALUSrc_B_EX(ALUSrc_B_EXE),.ALUC_EX(ALUControl_EXE),
   126	        .DatatoReg_EX(DatatoReg_EXE),.RegWrite_EX(RegWrite_EXE),.WR_EX(mem_w_EXE),
   127	        .u_b_h_w_EX(u_b_h_w_EXE),.MIO_EX(MIO_EXE));
   128	    
   129	    // ALU A 通道：寄存器值或 PC（AUIPC/JAL/JALR）
   130	    MUX2T1_32 mux_A_EXE(.I0(rs1_data_EXE),.I1(PC_EXE),.s(ALUSrc_A_EXE),.o(ALUA_EXE));
   131	
   132	    // ALU B 通道：寄存器值或立即数
   133	    MUX2T1_32 mux_B_EXE(.I0(rs2_data_EXE),.I1(Imm_EXE),.s(ALUSrc_B_EXE),.o(ALUB_EXE));
   134	
   135	    ALU alu(.A(ALUA_EXE),.B(ALUB_EXE),.Control(ALUControl_EXE),
   136	        .res(ALUout_EXE),.zero(ALUzero_EXE),.overflow(ALUoverflow_EXE));
   137	    
   138	    // store 写数据的前递通路：MEM 段结果 -> EX 段的 rs2
   139	    MUX2T1_32 mux_forward_EXE(.I0(rs2_data_EXE),.I1(mem_fwd_data),.s(forward_ctrl_ls),.o(Dataout_EXE));
   140	
   141	
   142	    // MEM
   143	    REG_EX_MEM reg_EXE_MEM(.clk(debug_clk),.rst(rst),.EN(reg_EM_EN),.flush(reg_EM_flush),
   144	        .IR_EX(inst_EXE),.PCurrent_EX(PC_EXE),.ALUO_EX(ALUout_EXE),.B_EX(Dataout_EXE),
   145	        .rd_EX(rd_EXE),.DatatoReg_EX(DatatoReg_EXE),.RegWrite_EX(RegWrite_EXE),
   146	        .WR_EX(mem_w_EXE),.u_b_h_w_EX(u_b_h_w_EXE),.MIO_EX(MIO_EXE),
   147	
   148	        .PCurrent_MEM(PC_MEM),.IR_MEM(inst_MEM),.ALUO_MEM(ALUout_MEM),.Datao_MEM(Dataout_MEM),
   149	        .rd_MEM(rd_MEM),.DatatoReg_MEM(DatatoReg_MEM),.RegWrite_MEM(RegWrite_MEM),
   150	        .WR_MEM(mem_w_MEM),.u_b_h_w_MEM(u_b_h_w_MEM),.MIO_MEM(MIO_MEM));
   151	    
   152	    RAM_B data_ram(.addra(ALUout_MEM),.clka(debug_clk),.dina(Dataout_MEM), 
   153	        .wea(mem_w_MEM),.douta(Datain_MEM),.mem_u_b_h_w(u_b_h_w_MEM));
   154	
   155	
   156	    // WB
   157	    REG_MEM_WB reg_MEM_WB(.clk(debug_clk),.rst(rst),.EN(reg_MW_EN),.IR_MEM(inst_MEM),
   158	        .PCurrent_MEM(PC_MEM),.ALUO_MEM(ALUout_MEM),.Datai(Datain_MEM),.rd_MEM(rd_MEM),
   159	        .DatatoReg_MEM(DatatoReg_MEM),.RegWrite_MEM(RegWrite_MEM),
   160	
   161	        .PCurrent_WB(PC_WB),.IR_WB(inst_WB),.ALUO_WB(ALUout_WB),.MDR_WB(Datain_WB),
   162	        .rd_WB(rd_WB),.DatatoReg_WB(DatatoReg_WB),.RegWrite_WB(RegWrite_WB));
   163	    
   164	    MUX2T1_32 mux_WB(.I0(ALUout_WB),.I1(Datain_WB),.s(DatatoReg_WB),.o(wt_data_WB));
   165	
   166	
   167	    wire [31:0] Test_signal;
   168	    assign debug_data = debug_addr[5] ? Test_signal : Debug_regs;
   169	    assign pc = PC_WB;
   170	    assign inst = inst_WB;
   171	    assign mem_addr = ALUout_MEM;
   172	    assign mem_data = Datain_MEM;
   173	
   174	endmodule=============== core/CtrlUnit.v
     1	`timescale 1ns / 1ps
     2	
     3	
     4	module CtrlUnit(
     5	    input[31:0] inst,
     6	    input cmp_res,
     7	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
     8	        MIO, rs1use, rs2use,
     9	    output [1:0] hazard_optype,
    10	    output [2:0] ImmSel, cmp_ctrl,
    11	    output [3:0] ALUControl,
    12	    output JALR
    13	);
    14	
    15	    wire[6:0] funct7 = inst[31:25];
    16	    wire[2:0] funct3 = inst[14:12];
    17	    wire[6:0] opcode = inst[6:0];
    18	
    19	    wire Rop = opcode == 7'b0110011;
    20	    wire Iop = opcode == 7'b0010011;
    21	    wire Bop = opcode == 7'b1100011;
    22	    wire Lop = opcode == 7'b0000011;
    23	    wire Sop = opcode == 7'b0100011;
    24	
    25	    wire funct7_0  = funct7 == 7'h0;
    26	    wire funct7_32 = funct7 == 7'h20;
    27	
    28	    wire funct3_0 = funct3 == 3'h0;
    29	    wire funct3_1 = funct3 == 3'h1;
    30	    wire funct3_2 = funct3 == 3'h2;
    31	    wire funct3_3 = funct3 == 3'h3;
    32	    wire funct3_4 = funct3 == 3'h4;
    33	    wire funct3_5 = funct3 == 3'h5;
    34	    wire funct3_6 = funct3 == 3'h6;
    35	    wire funct3_7 = funct3 == 3'h7;
    36	
    37	    wire ADD  = Rop & funct3_0 & funct7_0;
    38	    wire SUB  = Rop & funct3_0 & funct7_32;
    39	    wire SLL  = Rop & funct3_1 & funct7_0;
    40	    wire SLT  = Rop & funct3_2 & funct7_0;
    41	    wire SLTU = Rop & funct3_3 & funct7_0;
    42	    wire XOR  = Rop & funct3_4 & funct7_0;
    43	    wire SRL  = Rop & funct3_5 & funct7_0;
    44	    wire SRA  = Rop & funct3_5 & funct7_32;
    45	    wire OR   = Rop & funct3_6 & funct7_0;
    46	    wire AND  = Rop & funct3_7 & funct7_0;
    47	
    48	    wire ADDI  = Iop & funct3_0;	
    49	    wire SLTI  = Iop & funct3_2;
    50	    wire SLTIU = Iop & funct3_3;
    51	    wire XORI  = Iop & funct3_4;
    52	    wire ORI   = Iop & funct3_6;
    53	    wire ANDI  = Iop & funct3_7;
    54	    wire SLLI  = Iop & funct3_1 & funct7_0;
    55	    wire SRLI  = Iop & funct3_5 & funct7_0;
    56	    wire SRAI  = Iop & funct3_5 & funct7_32;
    57	
    58	    // 分支指令：由 Bop 与 funct3 译码
    59	    wire BEQ  = Bop & funct3_0;
    60	    wire BNE  = Bop & funct3_1;
    61	    wire BLT  = Bop & funct3_4;
    62	    wire BGE  = Bop & funct3_5;
    63	    wire BLTU = Bop & funct3_6;
    64	    wire BGEU = Bop & funct3_7;
    65	
    66	    // 访存读指令：由 Lop 与 funct3 译码
    67	    wire LB  = Lop & funct3_0;
    68	    wire LH  = Lop & funct3_1;
    69	    wire LW  = Lop & funct3_2;
    70	    wire LBU = Lop & funct3_4;
    71	    wire LHU = Lop & funct3_5;
    72	
    73	    // 访存写指令：由 Sop 与 funct3 译码
    74	    wire SB = Sop & funct3_0;
    75	    wire SH = Sop & funct3_1;
    76	    wire SW = Sop & funct3_2;
    77	
    78	    wire LUI   = opcode == 7'b0110111;
    79	    wire AUIPC = opcode == 7'b0010111;
    80	
    81	    wire JAL  = opcode == 7'b1101111;
    82	    assign JALR = (opcode == 7'b1100111) & funct3_0;
    83	
    84	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
    85	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
    86	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
    87	    wire L_valid = LW | LH | LB | LHU | LBU;
    88	    wire S_valid = SW | SH | SB;
    89	
    90	
    91	    // 实现：条件分支成立或无条件跳转时置位 Branch（即"发生跳转"）
    92	    assign Branch = (B_valid & cmp_res) | JAL | JALR;
    93	
    94	    parameter Imm_type_I = 3'b001;
    95	    parameter Imm_type_B = 3'b010;
    96	    parameter Imm_type_J = 3'b011;
    97	    parameter Imm_type_S = 3'b100;
    98	    parameter Imm_type_U = 3'b101;
    99	    assign ImmSel = {3{I_valid | JALR | L_valid}} & Imm_type_I |
   100	                    {3{B_valid}}                  & Imm_type_B |
   101	                    {3{JAL}}                      & Imm_type_J |
   102	                    {3{S_valid}}                  & Imm_type_S |
   103	                    {3{LUI | AUIPC}}              & Imm_type_U ;
   104	
   105	
   106	    localparam cmp_EQ  = 3'b001;
   107	    localparam cmp_NE  = 3'b010;
   108	    localparam cmp_LT  = 3'b011;
   109	    localparam cmp_LTU = 3'b100;
   110	    localparam cmp_GE  = 3'b101;
   111	    localparam cmp_GEU = 3'b110;
   112	    // 实现：根据分支子类型选择 cmp_32 的比较方式
   113	    assign cmp_ctrl = {3{BEQ }} & cmp_EQ  |
   114	                      {3{BNE }} & cmp_NE  |
   115	                      {3{BLT }} & cmp_LT  |
   116	                      {3{BLTU}} & cmp_LTU |
   117	                      {3{BGE }} & cmp_GE  |
   118	                      {3{BGEU}} & cmp_GEU ;
   119	
   120	    // 实现：AUIPC/JAL/JALR 使用 PC 作为 ALU 的 A 操作数
   121	    assign ALUSrc_A = AUIPC | JAL | JALR;
   122	
   123	    // 实现：立即数类指令使用立即数作为 ALU 的 B 操作数
   124	    assign ALUSrc_B = I_valid | L_valid | S_valid | LUI | AUIPC | JAL | JALR;
   125	
   126	    parameter ALU_ADD  = 4'b0001;
   127	    parameter ALU_SUB  = 4'b0010;
   128	    parameter ALU_AND  = 4'b0011;
   129	    parameter ALU_OR   = 4'b0100;
   130	    parameter ALU_XOR  = 4'b0101;
   131	    parameter ALU_SLL  = 4'b0110;
   132	    parameter ALU_SRL  = 4'b0111;
   133	    parameter ALU_SLT  = 4'b1000;
   134	    parameter ALU_SLTU = 4'b1001;
   135	    parameter ALU_SRA  = 4'b1010;
   136	    parameter ALU_Ap4  = 4'b1011;
   137	    parameter ALU_Bout = 4'b1100;
   138	    assign ALUControl = {4{ADD | ADDI | L_valid | S_valid | AUIPC}} & ALU_ADD  |
   139	                        {4{SUB}}                                    & ALU_SUB  |
   140	                        {4{AND | ANDI}}                             & ALU_AND  |
   141	                        {4{OR | ORI}}                               & ALU_OR   |
   142	                        {4{XOR | XORI}}                             & ALU_XOR  |
   143	                        {4{SLL | SLLI}}                             & ALU_SLL  |
   144	                        {4{SRL | SRLI}}                             & ALU_SRL  |
   145	                        {4{SLT | SLTI}}                             & ALU_SLT  |
   146	                        {4{SLTU | SLTIU}}                           & ALU_SLTU |
   147	                        {4{SRA | SRAI}}                             & ALU_SRA  |
   148	                        {4{JAL | JALR}}                             & ALU_Ap4  |
   149	                        {4{LUI}}                                    & ALU_Bout ;
   150	
   151	    assign DatatoReg = L_valid;
   152	
   153	    assign RegWrite = R_valid | I_valid | JAL | JALR | L_valid | LUI | AUIPC;
   154	
   155	    assign mem_w = S_valid;
   156	
   157	    assign MIO = L_valid | S_valid;
   158	
   159	    // 实现：读取 rs1 的指令
   160	    assign rs1use = R_valid | I_valid | L_valid | S_valid | B_valid | JALR;
   161	
   162	    // 实现：读取 rs2 的指令
   163	    assign rs2use = R_valid | S_valid | B_valid;
   164	
   165	    localparam hazard_optype_NONE = 2'b00;   // 不写寄存器
   166	    localparam hazard_optype_ALU   = 2'b01;   // 结果在 EX 段产生
   167	    localparam hazard_optype_LOAD  = 2'b10;   // 结果在 MEM 段产生
   168	    // 实现：load 为 2'b10，其它写寄存器的指令为 2'b01，其余为 2'b00
   169	    assign hazard_optype = {2{L_valid}} & hazard_optype_LOAD |
   170	                           {2{R_valid | I_valid | LUI | AUIPC | JAL | JALR}} & hazard_optype_ALU ;
   171	
   172	endmodule=============== core/HazardDetectionUnit.v
     1	`timescale 1ps/1ps
     2	
     3	module HazardDetectionUnit(
     4	    input clk,
     5	    input Branch_ID, rs1use_ID, rs2use_ID,
     6	    input[1:0] hazard_optype_ID,
     7	    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
     8	    output PC_EN_IF, reg_FD_EN, reg_FD_stall, reg_FD_flush,
     9	        reg_DE_EN, reg_DE_flush, reg_EM_EN, reg_EM_flush, reg_MW_EN,
    10	    output forward_ctrl_ls,
    11	    output[1:0] forward_ctrl_A, forward_ctrl_B
    12	);
    13	    // 实现：竞争检测与前递控制
    14	    // Hints:
    15	    // - Stall (PC_EN_IF=0, reg_FD stall, reg_DE flush) when the instruction in EX
    16	    //   writes a register that the ID instruction reads.
    17	    // - Branch (reg_FD_flush=1) when Branch_ID is asserted; do NOT flush reg_DE.
    18	    // - forward_ctrl_A/B: select 2'b01 to forward from MEM stage when rd_MEM
    19	    //   matches the ID instruction's source register.
    20	    // - The register file has write-through for WB, so no explicit WB forwarding needed.
    21	    // - forward_ctrl_ls: forward MEM result to store data when rd_MEM == rs2_EXE.
    22	    // - Use hazard_optype_ID registered one cycle (to get EX stage type) for stall guard.
    23	
    24	    localparam hazard_optype_NONE = 2'b00;   // 不写寄存器
    25	    localparam hazard_optype_ALU  = 2'b01;   // 结果在 EX 段产生
    26	    localparam hazard_optype_LOAD = 2'b10;   // 结果在 MEM 段产生
    27	
    28	    // ID 段的 optype 打一拍得到 EX 段的 optype，打两拍得到 MEM 段的 optype。
    29	    // 这是必须的：REG_ID_EX 无条件锁存 rd，所以 store/branch 会带着一个无意义
    30	    // 的 rd 往下走，仅凭 rd_EXE / rd_MEM 判断会误报竞争。
    31	    reg[1:0] hazard_optype_EXE = hazard_optype_NONE;
    32	    reg[1:0] hazard_optype_MEM = hazard_optype_NONE;
    33	
    34	    always @(posedge clk) begin
    35	        hazard_optype_EXE <= hazard_optype_ID;
    36	        hazard_optype_MEM <= hazard_optype_EXE;
    37	    end
    38	
    39	    // EX / MEM 段的指令是否真的会写一个非 x0 的寄存器
    40	    wire EXE_write = (hazard_optype_EXE != hazard_optype_NONE) & (rd_EXE != 5'b0);
    41	    wire MEM_write = (hazard_optype_MEM != hazard_optype_NONE) & (rd_MEM != 5'b0);
    42	
    43	    // 前递在 ID 段完成，EX 段的结果此时还不存在 => 只能停一拍
    44	    wire stall = EXE_write & ((rs1use_ID & (rs1_ID == rd_EXE)) |
    45	                              (rs2use_ID & (rs2_ID == rd_EXE)));
    46	
    47	    assign PC_EN_IF     = ~stall;       // 停顿时冻结 PC
    48	    assign reg_FD_EN    = 1'b1;
    49	    assign reg_FD_stall = stall;        // IF/ID 保持原值
    50	    assign reg_FD_flush = Branch_ID;    // 跳转发生时清掉顺序取回的那条指令
    51	    assign reg_DE_EN    = 1'b1;
    52	    assign reg_DE_flush = stall;        // 向 EX 段注入气泡
    53	    assign reg_EM_EN    = 1'b1;
    54	    assign reg_EM_flush = 1'b0;
    55	    assign reg_MW_EN    = 1'b1;
    56	
    57	    // MEM 段结果前递到 ID 段的两个源操作数
    58	    assign forward_ctrl_A  = (MEM_write & rs1use_ID & (rs1_ID == rd_MEM)) ? 2'b01 : 2'b00;
    59	    assign forward_ctrl_B  = (MEM_write & rs2use_ID & (rs2_ID == rd_MEM)) ? 2'b01 : 2'b00;
    60	
    61	    // MEM 段结果前递到 EX 段 store 指令的写数据
    62	    assign forward_ctrl_ls = MEM_write & (rd_MEM == rs2_EXE);
    63	
    64	endmodule

