    21	
    22	module    REG_IF_ID(input clk,                                      //IF/ID Latch
    23	                    input rst,
    24	                    input EN,                                       //流水寄存器使能
    25	                    input Data_stall,                               //数据竞争等待
    26	                    input flush,                                    //控制竞争清除并等待
    27	                    input [31:0] PCOUT,                             //指令存储器指针
    28	                    input [31:0] IR,                                //指令存储器输出
    29	
    30	                    output reg[31:0] IR_ID,                         //取指锁存
    31	                    output reg[31:0] PCurrent_ID                    //当前存在指令地址
    32	                );
    33	
    34	    // 实现：IF/ID 流水寄存器
    35	    // On reset: clear IR_ID and PCurrent_ID to 0.
    36	    // When EN is asserted:
    37	    //   - If Data_stall: hold current values (stall the pipeline stage)
    38	    //   - Else if flush: replace IR_ID with NOP (32'h00000013), hold PCurrent_ID
    39	    //   - Else: latch new instruction IR and program counter PCOUT
    40	    // When EN is deasserted: hold current values.
    41	    // 注意：数据竞争等待(Data_stall)的优先级高于控制竞争清除(flush)，
    42	    // 这样被 stall 住的跳转指令不会丢掉它后面那条已经取回的指令。
    43	    always @(posedge clk) begin
    44	        if (rst) begin
    45	            IR_ID       <= 32'h00000000;
    46	            PCurrent_ID <= 32'h00000000;
    47	        end
    48	        else if (EN) begin
    49	            if (Data_stall) begin           // 数据竞争：保持原值
    50	                IR_ID       <= IR_ID;
    51	                PCurrent_ID <= PCurrent_ID;
    52	            end
    53	            else if (flush) begin           // 控制竞争：插入 NOP 气泡
    54	                IR_ID       <= 32'h00000013;
    55	                PCurrent_ID <= PCurrent_ID;
    56	            end
    57	            else begin
    58	                IR_ID       <= IR;
    59	                PCurrent_ID <= PCOUT;
    60	            end
    61	        end
    62	    end
    63	
    64	endmodule=============== core/REG_ID_EX.v
