`timescale 1ns / 1ps
// Independent verification testbench for lab1 (written by the verifier, not the implementer).
// Compares the CPU's retire trace / issued-PC stream / final memory / final regfile
// against a golden model generated by ref_model.py.

module tb_lab1;
    reg clk, rst;
    wire [31:0] debug_data;
    wire [31:0] o_pc, o_inst, o_mem_addr, o_mem_data;
    reg [6:0] dbg_addr;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(dbg_addr),
        .debug_data(debug_data), .clk(clk), .rst(rst), .interrupter(1'b0),
        .pc(o_pc), .inst(o_inst), .mem_addr(o_mem_addr), .mem_data(o_mem_data));

    integer errors = 0;
    integer warns  = 0;

    // ---------------- golden data ----------------
    parameter MAXT = 200;
    reg [31:0] g_pc  [0:MAXT-1];
    reg [4:0]  g_rd  [0:MAXT-1];
    reg [31:0] g_val [0:MAXT-1];
    integer    g_n;
    reg [31:0] g_ipc [0:MAXT-1];
    integer    g_in;
    reg [7:0]  g_mem [0:127];
    reg [31:0] g_reg [0:31];

    integer fd, code, i;
    reg [31:0] t0, t2; reg [4:0] t1;

    // ---------------- observed ----------------
    integer r_n = 0;   // retire count
    integer i_n = 0;   // issue count
    integer cyc = 0;
    integer xerr = 0;

    task chk32; input [255:0] nm; input [31:0] exp; input [31:0] got; begin
        if (exp !== got) begin
            $display("  FAIL %0s : expected %08h got %08h", nm, exp, got);
            errors = errors + 1;
        end
    end endtask

    initial begin
        clk = 0; rst = 1; dbg_addr = 7'd0;
        #2 rst = 0;
    end
    always #1 clk = ~clk;

    // ------- load golden -------
    initial begin
        g_n = 0;
        fd = $fopen("golden_trace.txt", "r");
        if (fd == 0) begin $display("cannot open golden_trace.txt"); $finish; end
        code = $fscanf(fd, "%h %d %h\n", t0, t1, t2);
        while (code == 3) begin
            g_pc[g_n] = t0; g_rd[g_n] = t1; g_val[g_n] = t2; g_n = g_n + 1;
            code = $fscanf(fd, "%h %d %h\n", t0, t1, t2);
        end
        $fclose(fd);

        g_in = 0;
        fd = $fopen("golden_pcs.txt", "r");
        code = $fscanf(fd, "%h\n", t0);
        while (code == 1) begin
            g_ipc[g_in] = t0; g_in = g_in + 1;
            code = $fscanf(fd, "%h\n", t0);
        end
        $fclose(fd);

        $readmemh("golden_mem.txt", g_mem);
        fd = $fopen("golden_regs.txt", "r");
        for (i = 0; i < 32; i = i + 1) begin
            code = $fscanf(fd, "%d %h\n", t1, t2);
            g_reg[i] = t2;
        end
        $fclose(fd);
        $display("golden: %0d retires, %0d issues", g_n, g_in);
    end

    // ------- observe retires (sample on negedge, values settled after posedge) -------
    always @(negedge clk) if (!rst) begin
        cyc = cyc + 1;
        // X/Z hygiene on control signals that must never be unknown
        if (^{core.RegWrite_WB, core.reg_FD_stall, core.reg_FD_flush, core.Branch_ctrl,
              core.PC_EN_IF, core.reg_DE_flush} === 1'bx) begin
            if (xerr < 5) $display("  FAIL cycle %0d: X/Z on core control signals", cyc);
            xerr = xerr + 1; errors = errors + 1;
        end
        if (^core.PC_IF === 1'bx) begin
            if (xerr < 5) $display("  FAIL cycle %0d: X on PC_IF", cyc);
            xerr = xerr + 1; errors = errors + 1;
        end

        if (core.RegWrite_WB === 1'b1 && core.rd_WB != 5'b0) begin
            if (r_n < g_n) begin
                if (core.PC_WB !== g_pc[r_n] || core.rd_WB !== g_rd[r_n] ||
                    core.wt_data_WB !== g_val[r_n]) begin
                    $display("  FAIL retire[%0d]: exp PC=%08h rd=x%0d val=%08h | got PC=%08h rd=x%0d val=%08h",
                        r_n, g_pc[r_n], g_rd[r_n], g_val[r_n],
                        core.PC_WB, core.rd_WB, core.wt_data_WB);
                    errors = errors + 1;
                end
            end
            r_n = r_n + 1;
        end

        // issued-PC stream: PC_IF is committed into IF/ID at the next posedge
        // unless the IF/ID register stalls (holds) or is flushed (squashed).
        if (core.reg_FD_stall !== 1'b1 && core.reg_FD_flush !== 1'b1 && core.reg_FD_EN === 1'b1) begin
            if (i_n < g_in) begin
                if (core.PC_IF !== g_ipc[i_n]) begin
                    $display("  FAIL issue[%0d]: expected PC=%08h got PC=%08h", i_n, g_ipc[i_n], core.PC_IF);
                    errors = errors + 1;
                end
            end
            i_n = i_n + 1;
        end
    end

    integer nchecked;
    initial begin
        #2;                       // release reset
        wait (r_n >= 41);         // whole program retired once
        #40;                      // let the tail drain
        $display("--- observed %0d retires, %0d issues in %0d cycles ---", r_n, i_n, cyc);

        if (r_n < 41) begin
            $display("  FAIL: only %0d retires observed (expected >= 41)", r_n);
            errors = errors + 1;
        end
        if (i_n < 60) begin
            $display("  FAIL: only %0d issues observed (expected >= 60)", i_n);
            errors = errors + 1;
        end

        // ---- final data memory (first 48 bytes cover everything the program touches) ----
        nchecked = 0;
        for (i = 0; i < 48; i = i + 1) begin
            if (core.data_ram.data[i] !== g_mem[i]) begin
                $display("  FAIL mem[%0d]: expected %02h got %02h", i, g_mem[i], core.data_ram.data[i]);
                errors = errors + 1;
            end
            nchecked = nchecked + 1;
        end
        $display("  checked %0d RAM bytes", nchecked);

        // ---- architectural register file after the 41st retire (+drain) ----
        //      (program loops, so only check the registers that are stable)
        for (i = 1; i < 32; i = i + 1) begin
            if (^core.register.register[i] === 1'bx) begin
                $display("  FAIL x%0d is X", i);
                errors = errors + 1;
            end
        end
        // spot-check the debug read port
        dbg_addr = 7'd4; #0.01;
        if (debug_data !== core.register.register[4]) begin
            $display("  FAIL debug port: got %08h expected %08h", debug_data, core.register.register[4]);
            errors = errors + 1;
        end
        dbg_addr = 7'd0; #0.01;
        if (debug_data !== 32'h0) begin
            $display("  FAIL debug port x0: got %08h", debug_data);
            errors = errors + 1;
        end

        if (errors == 0) $display("RESULT: PASS (0 errors)");
        else             $display("RESULT: FAIL (%0d errors)", errors);
        $finish;
    end

    initial begin
        #4000;
        $display("RESULT: FAIL (timeout, r_n=%0d)", r_n);
        $finish;
    end
endmodule

