// Mid-run reset test: assert rst partway through execution and confirm the CPU
// restarts cleanly from PC 0 and reproduces the same retire trace.
module tb_reset;
    reg clk, rst;
    wire [31:0] debug_data;
    RV32core core(.debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'd0),
        .debug_data(debug_data), .clk(clk), .rst(rst), .interrupter(1'b0));

    integer errors = 0, r_n = 0, i, g_n;
    reg [31:0] g_pc[0:199]; reg [4:0] g_rd[0:199]; reg [31:0] g_val[0:199];
    integer fd, code; reg [31:0] t0, t2; reg [4:0] t1;
    reg armed = 0;

    initial begin clk = 0; rst = 1; #2 rst = 0; end
    always #1 clk = ~clk;

    initial begin
        g_n = 0;
        fd = $fopen("golden_trace.txt", "r");
        code = $fscanf(fd, "%h %d %h\n", t0, t1, t2);
        while (code == 3 && g_n < 200) begin
            g_pc[g_n] = t0; g_rd[g_n] = t1; g_val[g_n] = t2; g_n = g_n + 1;
            code = $fscanf(fd, "%h %d %h\n", t0, t1, t2);
        end
        $fclose(fd);
    end

    always @(negedge clk) if (!rst && armed) begin
        if (core.RegWrite_WB === 1'b1 && core.rd_WB != 5'b0) begin
            if (r_n < 41) begin
                if (core.PC_WB !== g_pc[r_n] || core.rd_WB !== g_rd[r_n] || core.wt_data_WB !== g_val[r_n]) begin
                    $display("  FAIL post-reset retire[%0d]: exp PC=%08h rd=x%0d val=%08h | got PC=%08h rd=x%0d val=%08h",
                        r_n, g_pc[r_n], g_rd[r_n], g_val[r_n], core.PC_WB, core.rd_WB, core.wt_data_WB);
                    errors = errors + 1;
                end
            end
            r_n = r_n + 1;
        end
    end

    initial begin
        #61;                 // let it run ~30 cycles into the program
        rst = 1; #4; rst = 0;
        if (core.PC_IF !== 32'd0) begin
            $display("  FAIL: PC_IF = %08h after reset, expected 0", core.PC_IF);
            errors = errors + 1;
        end
        for (i = 1; i < 32; i = i + 1)
            if (core.register.register[i] !== 32'd0) begin
                $display("  FAIL: x%0d = %08h after reset, expected 0", i, core.register.register[i]);
                errors = errors + 1;
            end
        if (core.RegWrite_WB !== 1'b0 || core.rd_WB !== 5'd0 || core.inst_WB !== 32'd0) begin
            $display("  FAIL: WB stage not cleared by reset (RegWrite=%b rd=%0d inst=%08h)",
                     core.RegWrite_WB, core.rd_WB, core.inst_WB);
            errors = errors + 1;
        end
        armed = 1;
        wait (r_n >= 41);
        #10;
        $display("--- post-reset: %0d retires replayed ---", r_n);
        if (errors == 0) $display("RESULT: PASS (0 errors)");
        else             $display("RESULT: FAIL (%0d errors)", errors);
        $finish;
    end
    initial begin #4000; $display("RESULT: FAIL (timeout r_n=%0d)", r_n); $finish; end
endmodule

